// PLACEHOLDER CONTENT IN THIS MIGRATION
// The seed inserts below produce dev/demo data clearly flagged with is_placeholder = 1.
// When the content team delivers the real prompt library, write a 0002 migration that
// DELETEs WHERE is_placeholder = 1 and INSERTs the real content. Do not edit this file.

import * as SQLite from 'expo-sqlite';

const SCHEMA = `
  CREATE TABLE categories (
    id             TEXT PRIMARY KEY,
    name           TEXT NOT NULL,
    description    TEXT,
    display_order  INTEGER NOT NULL DEFAULT 0,
    icon           TEXT,
    is_placeholder INTEGER NOT NULL DEFAULT 0
  );

  CREATE TABLE tags (
    id             TEXT PRIMARY KEY,
    category_id    TEXT REFERENCES categories(id),
    label          TEXT NOT NULL,
    is_placeholder INTEGER NOT NULL DEFAULT 0
  );

  CREATE TABLE liminal_spaces (
    id             TEXT PRIMARY KEY,
    name           TEXT NOT NULL,
    description    TEXT,
    icon           TEXT,
    display_order  INTEGER NOT NULL DEFAULT 0,
    is_placeholder INTEGER NOT NULL DEFAULT 0
  );

  CREATE TABLE prompts (
    id             TEXT PRIMARY KEY,
    age_group      TEXT NOT NULL,
    category_id    TEXT REFERENCES categories(id),
    text           TEXT NOT NULL,
    full_question  TEXT NOT NULL DEFAULT 'What are all the things you can think of that you could do?',
    tier           TEXT NOT NULL DEFAULT 'free' CHECK (tier IN ('free','premium','professional')),
    source         TEXT NOT NULL DEFAULT 'official',
    liminal_space  TEXT REFERENCES liminal_spaces(id),
    parent_askable INTEGER NOT NULL DEFAULT 0,
    is_active      INTEGER NOT NULL DEFAULT 1,
    is_placeholder INTEGER NOT NULL DEFAULT 0,
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL
  );

  CREATE INDEX idx_prompts_age_group ON prompts(age_group, is_active);
  CREATE INDEX idx_prompts_category ON prompts(category_id);
  CREATE INDEX idx_prompts_liminal_space ON prompts(liminal_space);

  CREATE TABLE prompt_tags (
    prompt_id TEXT NOT NULL REFERENCES prompts(id) ON DELETE CASCADE,
    tag_id    TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
    PRIMARY KEY (prompt_id, tag_id)
  );

  CREATE TABLE tips (
    id             TEXT PRIMARY KEY,
    prompt_id      TEXT REFERENCES prompts(id) ON DELETE CASCADE,
    kind           TEXT NOT NULL CHECK (kind IN ('kickstarter','discussion','follow_up','safety_note')),
    body           TEXT NOT NULL,
    audience       TEXT NOT NULL DEFAULT 'adult' CHECK (audience IN ('adult','child','either')),
    display_order  INTEGER NOT NULL DEFAULT 0,
    is_placeholder INTEGER NOT NULL DEFAULT 0
  );

  CREATE INDEX idx_tips_prompt ON tips(prompt_id);

  CREATE TABLE world_building (
    id             TEXT PRIMARY KEY,
    prompt_id      TEXT NOT NULL REFERENCES prompts(id) ON DELETE CASCADE,
    card_text      TEXT NOT NULL,
    display_order  INTEGER NOT NULL DEFAULT 0,
    difficulty     INTEGER NOT NULL DEFAULT 1,
    is_placeholder INTEGER NOT NULL DEFAULT 0
  );

  CREATE INDEX idx_world_building_prompt ON world_building(prompt_id);

  CREATE TABLE contexts (
    id                  TEXT PRIMARY KEY,
    label               TEXT NOT NULL,
    age_group_default   TEXT,
    is_anonymous        INTEGER NOT NULL DEFAULT 0,
    color_token         TEXT,
    created_at          TEXT NOT NULL,
    archived_at         TEXT
  );

  CREATE TABLE favorites (
    context_id   TEXT NOT NULL REFERENCES contexts(id) ON DELETE CASCADE,
    prompt_id    TEXT NOT NULL REFERENCES prompts(id) ON DELETE CASCADE,
    favorited_at TEXT NOT NULL,
    PRIMARY KEY (context_id, prompt_id)
  );

  CREATE INDEX idx_favorites_context ON favorites(context_id);

  CREATE TABLE reflections (
    id         TEXT PRIMARY KEY,
    context_id TEXT NOT NULL REFERENCES contexts(id) ON DELETE CASCADE,
    prompt_id  TEXT NOT NULL REFERENCES prompts(id),
    note       TEXT,
    audio_uri  TEXT,
    rating     INTEGER,
    created_at TEXT NOT NULL
  );

  CREATE INDEX idx_reflections_context_prompt ON reflections(context_id, prompt_id);

  CREATE TABLE personalization (
    context_id TEXT NOT NULL REFERENCES contexts(id) ON DELETE CASCADE,
    key        TEXT NOT NULL,
    value      TEXT NOT NULL,
    PRIMARY KEY (context_id, key)
  );

  CREATE TABLE modules (
    id             TEXT PRIMARY KEY,
    title          TEXT NOT NULL,
    description    TEXT,
    age_group      TEXT,
    category_id    TEXT REFERENCES categories(id),
    duration_days  INTEGER NOT NULL DEFAULT 5,
    tier           TEXT NOT NULL DEFAULT 'free',
    cover_color    TEXT,
    display_order  INTEGER NOT NULL DEFAULT 0,
    is_placeholder INTEGER NOT NULL DEFAULT 0
  );

  CREATE TABLE module_steps (
    module_id   TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE,
    step_number INTEGER NOT NULL,
    prompt_id   TEXT NOT NULL REFERENCES prompts(id),
    intro_text  TEXT,
    outro_text  TEXT,
    PRIMARY KEY (module_id, step_number)
  );

  CREATE TABLE module_progress (
    context_id   TEXT NOT NULL REFERENCES contexts(id) ON DELETE CASCADE,
    module_id    TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE,
    prompt_id    TEXT NOT NULL REFERENCES prompts(id),
    completed_at TEXT,
    PRIMARY KEY (context_id, module_id, prompt_id)
  );
`;

